import{_ as o,o as a,c as r,a2 as d}from"./chunks/framework.DnrXFDHb.js";const p=JSON.parse('{"title":"小算力中心前期报批，就三道闸：备案、能评、通电","description":"","frontmatter":{"title":"小算力中心前期报批，就三道闸：备案、能评、通电","updated":"2026-09-16T00:00:00.000Z","visibility":"public"},"headers":[],"relativePath":"智算中心投建运/小型算力中心前期报批清单_五城备案能评电力接入全流程.md","filePath":"智算中心投建运/小型算力中心前期报批清单_五城备案能评电力接入全流程.md","lastUpdated":null}'),e={name:"智算中心投建运/小型算力中心前期报批清单_五城备案能评电力接入全流程.md"};function l(n,t,i,u,h,s){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="小算力中心前期报批-就三道闸-备案、能评、通电——沪苏杭穗深五城清单" tabindex="-1">小算力中心前期报批，就三道闸：备案、能评、通电——沪苏杭穗深五城清单 <a class="header-anchor" href="#小算力中心前期报批-就三道闸-备案、能评、通电——沪苏杭穗深五城清单" aria-label="Permalink to &quot;小算力中心前期报批，就三道闸：备案、能评、通电——沪苏杭穗深五城清单&quot;">​</a></h1><blockquote><p><strong>公众号摘要</strong>（发布时填入摘要栏，不进入正文）：民资小型算力中心走的是备案制，窗口指导只管中大型项目——别被大智算的流程吓到。真正容易卡死的：能评（2025 年 9 月刚换过门槛）和电力接入。这篇把沪苏杭穗深五城的报批链路、对接部门、资料清单一次讲清，打印出来就能带去政务大厅。</p></blockquote><p>【封面图建议，发布时替换为实际图片】城市天际线背景下的机房透视写实图，前景放一张&quot;A4 清单&quot;卡片，备案 → 能评 → 通电三枚印章依次盖章，底部压主标题。</p><hr><p>我干了 20 年地产，管过基金、做过经营性物业的募投管退，最近几年又扎进电力交易和高压直流供电架构。现在开这个号，就是想用&quot;资产 + 电力&quot;的双重视角，把算电协同这件事讲清楚。本文由 AI 整理资料和初稿，但每一个判断——比如我说&quot;小型算力中心最容易死在能评和电力接入，不是备案&quot;——都是我自己的体感。AI 没去过项目现场，我没让它替我做判断。也欢迎您在评论区拍砖和切磋。</p><h3 id="先对号入座-你走备案制-还是窗口指导" tabindex="-1">先对号入座：你走备案制，还是窗口指导？ <a class="header-anchor" href="#先对号入座-你走备案制-还是窗口指导" aria-label="Permalink to &quot;先对号入座：你走备案制，还是窗口指导？&quot;">​</a></h3><p>说白了，窗口指导就是国家怕你乱建算力中心。2025 年 4 月，国家发改委牵头印发算力基础设施项目窗口指导相关文件，各地陆续启动算力摸底和项目申报【财联社 2025-04；广州市政府 2026-04】。业内通行的参考划档是这样：</p><ul><li><strong>大型</strong>：≥3000 标准机架，或服务器采购 ≥10 亿元 → 仅限国家枢纽节点，严格审批</li><li><strong>中型</strong>：1000–3000 机架，或服务器采购 3–10 亿元 → 地方/国企参与要走窗口指导，鼓励向枢纽集聚</li><li><strong>小型</strong>：不足 1000 机架 且 服务器采购 ❤️ 亿元 → <strong>纯社会资金出资的不纳入窗口指导，走备案制</strong>；地方/国企原则上不得出资建设</li></ul><p>（各地按此细化执行，具体以属地发改最新通知为准。）</p><p>这跟当年做商业地产一个道理：**政府出钱的项目和纯民营项目，是两套逻辑。**你先把这一定性做对——民资小项目 = 备案 + 能评 + 电力接入三件事，别被大型智算中心那套&quot;窗口指导—枢纽节点—严格审批&quot;的流程吓到。</p><p>先说清一件事：这张清单没有北京。北京是全国数据中心能评最严的城市——新建项目 PUE 按能耗分档压到 1.3 以内（3 万吨标煤以上的要求 ≤1.15），PUE 超 1.4 就要加收差别电价（京发改规〔2023〕10 号）。民资小项目在北京基本走不通，所以直接不列它，省得误导。做地产时我也常说：选城市先看政策土壤，别在第一关就耗死。</p><h3 id="一条主线-跟当年报规报建一个模子" tabindex="-1">一条主线：跟当年报规报建一个模子 <a class="header-anchor" href="#一条主线-跟当年报规报建一个模子" aria-label="Permalink to &quot;一条主线：跟当年报规报建一个模子&quot;">​</a></h3><p>土地/载体落实 → 项目备案 → 节能审查 → 环评（登记表为主）→ 规划许可 → 施工图联合审查 + 消防设计审查 → 施工许可 → 电力增容/供电接入（与报建并行推进）→ 竣工验收（联合验收）→ 运营资质（IDC 证，自用可免）</p><p>地产人秒懂：这跟拿地后报规报建一模一样，只是把&quot;商业业态&quot;换成了&quot;机架数和 PUE&quot;。唯一区别——<strong>电力接入这场戏，从来没像现在这么重要过</strong>，后面专门讲。</p><h3 id="逐环节拆解-资料-对接部门" tabindex="-1">逐环节拆解：资料 + 对接部门 <a class="header-anchor" href="#逐环节拆解-资料-对接部门" aria-label="Permalink to &quot;逐环节拆解：资料 + 对接部门&quot;">​</a></h3><h4 id="载体落实与项目备案-备案内容就是你的-规划证" tabindex="-1">载体落实与项目备案：备案内容就是你的&quot;规划证&quot; <a class="header-anchor" href="#载体落实与项目备案-备案内容就是你的-规划证" aria-label="Permalink to &quot;载体落实与项目备案：备案内容就是你的&quot;规划证&quot;&quot;">​</a></h4><table tabindex="0"><thead><tr><th>事项</th><th>对接部门</th><th>核心资料</th></tr></thead><tbody><tr><td>载体落实</td><td>自然资源局/园区管委会</td><td>不动产权证/租赁协议/用地规划许可</td></tr><tr><td>项目备案</td><td>发改或经信（各地不同）</td><td>备案申请表、营业执照、项目说明书（规模/投资/选址）、承诺声明</td></tr></tbody></table><p>五城备案渠道：</p><ul><li><strong>上海</strong>：市发改委备案；经信委另有&quot;用能指标支持意见&quot;（数据中心建设导则 2021 版）——宜在外环外布局，中心城区严控新建</li><li><strong>苏州</strong>：属地政务服务局/数据局牵头，&quot;多评合一&quot;</li><li><strong>杭州</strong>：浙江政务服务网&quot;固定资产投资项目审批一件事&quot;赋码</li><li><strong>广州</strong>：广东省投资项目在线审批监管平台，区发改局牵头</li><li><strong>深圳</strong>：市/区发改，深圳政务服务网，1–2 个工作日出备案证</li></ul><p>资产视角说一句：**备案内容必须和实际建设一致。**我见过商业地产项目，报建写&quot;写字楼&quot;结果盖了商场，后期融资直接被银行按违规处理。IDC 项目同理——备案写&quot;机房租赁&quot;结果建了智算集群，融资尽调时直接卡死。</p><h4 id="节能审查-2025-年-9-月刚换过门槛-最容易卡的死穴" tabindex="-1">节能审查：2025 年 9 月刚换过门槛（最容易卡的死穴） <a class="header-anchor" href="#节能审查-2025-年-9-月刚换过门槛-最容易卡的死穴" aria-label="Permalink to &quot;节能审查：2025 年 9 月刚换过门槛（最容易卡的死穴）&quot;">​</a></h4><p>国家能评豁免线，换口径了：</p><ul><li>旧口径（2023 年第 2 号令，已废止）：年综合能耗 &lt;1000 吨标煤 <strong>且</strong> 年电力 &lt;500 万千瓦时 → 免单独能评</li><li>新口径（2025 年第 31 号令，2025-09-01 起施行）：年综合能耗 &lt;1000 吨标煤 <strong>且</strong> 年煤炭消费量 &lt;1000 吨 → 免单独能评。<strong>数据中心不烧煤，卡你的只剩&quot;年综合能耗 1000 吨标煤&quot;这一条</strong>——电力按当量值折算，约合一年 810 多万度电</li></ul><p>一句话：新规比老规宽了，那根&quot;500 万千瓦时&quot;的电力线取消了。但别高兴太早：折标系数各地取当量值还是等价值不一样，报建前先电话问属地发改；而且多数省市对数据中心另有能耗约束（上海用能指标、广东能耗保障机制、珠三角向韶关引导）——<strong>&quot;免能评&quot;不等于&quot;留得住用电指标&quot;。</strong></p><p>这事跟 GB200 一进来就全变了：一个 GB200 NVL72 整柜满载就是 120–132kW（NVIDIA/HPE 规格书口径），一年烧 110 多万度电——**一个柜子，顶三百来户城市家庭一年的电。**按当量值算，7 个柜子满载一年就摸到豁免线；现实点算负载率，十几个柜子也跑不掉。所以&quot;小型&quot;别只看机架数，<strong>年电力消费量才是生死线。</strong></p><p>老地产的话讲——以前电费是物业费，现在电费是房贷，这账一变，整个资产模型都要重算。</p><p>各市审查机关：上海——市发改委（大额项目）/区级；苏州——区发改（多评合一并联）；杭州——市/区发改按能耗分级，网办即办；广州——区发改牵头；深圳——市发改委按权限分级。</p><blockquote><p>我跟你讲个真事：有同行拿&quot;机架数不超 1000&quot;当免能评的护身符，结果年电力超线，能评报告补了半年——备案都下来了，开工硬生生往后拖。报建第一件事，先把年电量算清楚。</p></blockquote><h4 id="环评-数据中心通常只填登记表" tabindex="-1">环评：数据中心通常只填登记表 <a class="header-anchor" href="#环评-数据中心通常只填登记表" aria-label="Permalink to &quot;环评：数据中心通常只填登记表&quot;">​</a></h4><p>数据中心不在报告书/报告表强制名录，一般填<strong>环境影响登记表</strong>（备案制）即可：对接生态环境局（上海一网通办/深圳政务服务网等）。资料：申请表、项目说明、噪声/废水/固废（冷却液）说明。<strong>液冷项目注意</strong>：冷却液的环境风险要单独写清楚，别偷懒——这跟当年商业地产改影院要单独过消防性能化一个道理，新工艺总在规范过渡期被多问一句。</p><h4 id="规划许可-施工图联合审查-消防设计审查" tabindex="-1">规划许可 + 施工图联合审查 + 消防设计审查 <a class="header-anchor" href="#规划许可-施工图联合审查-消防设计审查" aria-label="Permalink to &quot;规划许可 + 施工图联合审查 + 消防设计审查&quot;">​</a></h4><table tabindex="0"><thead><tr><th>环节</th><th>对接</th><th>要点</th></tr></thead><tbody><tr><td>用地/工程规划许可</td><td>自然资源局</td><td>备案证、能评意见、总平图、选址意见（杭州凭出让合同即时办）</td></tr><tr><td>施工图联合审查</td><td>住建（审图机构）</td><td>消防/人防/防雷并入（苏州多评合一、上海综合验收含防雷）</td></tr><tr><td>消防设计审查</td><td>住建消防审验处</td><td>数据中心属特殊建设工程必审；气体灭火选型、柴发储油间防爆是重点</td></tr></tbody></table><h4 id="施工许可" tabindex="-1">施工许可 <a class="header-anchor" href="#施工许可" aria-label="Permalink to &quot;施工许可&quot;">​</a></h4><p>住建局/行政审批局：前置条件是施工图合格书 + 消防设计审查意见 + 中标通知书 + 相关人员社保。上海纳入综合竣工验收前置，深圳走在线审批平台。</p><h4 id="电力增容-供电接入-算电协同的命门" tabindex="-1">电力增容 / 供电接入：算电协同的命门 <a class="header-anchor" href="#电力增容-供电接入-算电协同的命门" aria-label="Permalink to &quot;电力增容 / 供电接入：算电协同的命门&quot;">​</a></h4><p>**这部分决定你 CapEx 天花板和交付周期。**就像当年商业体开业前要通水电气——变电站远在几公里外，你就只有等。</p><p>五城对接主体：上海——国网上海（随申办/一网通办）；苏州——苏州供电（&quot;特快电力&quot;）；杭州——国网浙江（浙里办）；广州——南网广州供电局；深圳——南网深圳供电局。</p><p>几个关键动作：</p><ul><li><strong>早报装</strong>：拿到备案证就交用电意向，别等施工图——苏州对小工程甚至可&quot;预批先建&quot;</li><li><strong>供电方案答复后才排施工</strong>：双电源重要用户，方案答复可到 26 个工作日</li><li><strong>先问可开放容量</strong>：拿地前先问供电公司&quot;变电站在哪、还剩多少容量&quot;——就像当年做商业地产先查地铁口和市政管线</li><li>绿电直连/源网荷储：单独找发改能源处，不走常规报装</li></ul><h4 id="竣工验收-联合验收" tabindex="-1">竣工验收（联合验收） <a class="header-anchor" href="#竣工验收-联合验收" aria-label="Permalink to &quot;竣工验收（联合验收）&quot;">​</a></h4><p>上海综合竣工验收（一家牵头、统一受理）；苏州联合验收约 15 个工作日；杭州规划+消防+人防+城建档案在线联合；广州/深圳由住建牵头、一窗受理。通用资料：竣工图、消防验收合格书、人防/防雷意见、质检报告、档案验收。</p><h4 id="运营资质-idc-许可证" tabindex="-1">运营资质（IDC 许可证） <a class="header-anchor" href="#运营资质-idc-许可证" aria-label="Permalink to &quot;运营资质（IDC 许可证）&quot;">​</a></h4><p>对外经营（机柜租赁/算力服务）→ 增值电信业务经营许可证（B11 类 IDC），对接省通信管理局（省内）/工信部（跨区），周期常见 3–4 个月，等保测评、机房物理检测、消防验收证明缺一不可；仅内部自用 → <strong>免 IDC 证</strong>。</p><p>资产逻辑：自用边缘节点先跑起来、证后面补；<strong>对外招租的别省这一步</strong>——营收口径不合规，退出时估值直接打折。当年做地产基金，没产证或用途不符的物业，资产证券化根本进不了池子，一个道理。</p><h3 id="五城差异速查-一分钟对号入座" tabindex="-1">五城差异速查：一分钟对号入座 <a class="header-anchor" href="#五城差异速查-一分钟对号入座" aria-label="Permalink to &quot;五城差异速查：一分钟对号入座&quot;">​</a></h3><table tabindex="0"><thead><tr><th>城市</th><th>备案/牵头</th><th>能评要点</th><th>特色环节</th></tr></thead><tbody><tr><td>上海</td><td>市发改委备案；经信委出用能指标意见</td><td>综合能耗分级审查、报告评审+验收</td><td>综合竣工验收一家牵头</td></tr><tr><td>苏州</td><td>政务服务局/数据局，多评合一</td><td>区级发改并联</td><td>&quot;特快电力&quot;、小工程免规划审批、预批先建</td></tr><tr><td>杭州</td><td>浙里办&quot;审批一件事&quot;赋码</td><td>市/区发改按能耗分级、网办即办</td><td>审批一件事、最多&quot;90 天&quot;承诺</td></tr><tr><td>广州</td><td>省在线平台，区发改牵头</td><td>全省能耗保障机制约束（原则上不再新增机柜，边缘自用 &lt;1000 架除外）</td><td>南网&quot;两证&quot;办电；大型项目向韶关集群引导</td></tr><tr><td>深圳</td><td>市/区发改，1–2 个工作日备案</td><td>与国标一致；新建项目 PUE≤1.25</td><td>官方定义&quot;边缘数据中心&quot;：≤100 标准机架、新建 PUE≤1.5（深工信〔2023〕300 号）</td></tr></tbody></table><h3 id="地产老哥的风控三句话" tabindex="-1">地产老哥的风控三句话 <a class="header-anchor" href="#地产老哥的风控三句话" aria-label="Permalink to &quot;地产老哥的风控三句话&quot;">​</a></h3><ol><li><strong>别用大型智算的流程套边缘小节点</strong>——民资备案制，能评（看新口径）和电力接入才是真卡点</li><li><strong>电力接入周期 ≈ 变电站距离 + 审批层级</strong>——拿地前先问&quot;可开放容量&quot;，就像当年先查地铁口</li><li><strong>备案内容 = 实际建设</strong>，IDC 证按业务模式倒推——别等融资尽调才改口</li></ol><p>数据来源： [1] 国家发改委《固定资产投资项目节能审查和碳排放评价办法》（2025 年第 31 号令，自 2025-09-01 施行）｜能评豁免新口径 [2] 财联社（2025-04-16）｜发改委牵头算力基础设施窗口指导、各地摸底启动 [3] 广州市政府（2026-04-13）｜窗口指导文件落地与项目申报实例（黄埔 4 项目） [4] NVIDIA / HPE GB200 NVL72 规格（2025）｜整柜功率约 120–132kW [5] 深圳市算力基础设施高质量发展行动计划（深工信〔2023〕300 号）｜边缘数据中心定义与 PUE 目标</p><p>⚠️ 风险提示：地方政策与能耗口径变动｜电力接入延期。本文仅作产业研究，不构成任何投资建议。</p><p>关注「算电协同研习社」，也欢迎在评论区拍砖——一个人捋容易钻牛角尖，一群人捋才能捋透。</p><p>你那边窗口指导的口径，跟这篇对得上吗？哪个环节最卡？咱们评论区见。</p>',52)])])}const g=o(e,[["render",l]]);export{p as __pageData,g as default};
